_MISSING = object()


def _segments(path: str) -> list[str]:
    """Split a query path on the dots that are not inside a bracket."""
    segments: list[str] = []
    depth = 0
    current: list[str] = []
    for character in path:
        if character == "[":
            depth += 1
        elif character == "]":
            depth -= 1
        if character == "." and depth == 0:
            segments.append("".join(current))
            current = []
            continue
        current.append(character)
    if current:
        segments.append("".join(current))
    return segments


def _step(cursor: Any, segment: str) -> Any:
    """Apply one `name[bracket]...` query segment to the cursor."""
    name, _, rest = segment.partition("[")
